import*as THREE from'three';import{Port,materials}from'../../core/index.js';import{roundedRect}from'../../core/geometry.js';import{mesh,FACE,portQuaternion}from'../../modeling/parts.js';import{spec}from'./dimensions.js';import{TransparentOled}from'./TransparentOled.js';import{addStickers}from'./stickers.js';
const tau=Math.PI*2;function hole(s,x,y,r){const p=new THREE.Path();p.absarc(x,y,r,0,tau,false);s.holes.push(p);}const solid=(p,s,d,pos,mat,n)=>mesh(p,new THREE.ExtrudeGeometry(s,{depth:d,bevelEnabled:false,curveSegments:64}),mat,pos,n);
function ring(p,ro,ri,d,pos,mat,n){const s=new THREE.Shape();s.absarc(0,0,ro,0,tau,false);hole(s,0,0,ri);return solid(p,s,d,pos,mat,n);}
function outline(){const s=new THREE.Shape();s.moveTo(-21,23.5);s.lineTo(21,23.5);s.lineTo(21,-5.6);s.lineTo(20,-6.6);s.lineTo(20,-12.8);s.lineTo(21,-13.8);s.lineTo(21,-16.5);s.lineTo(19,-16.5);s.lineTo(19,-20.5);s.absarc(16,-20.5,3,0,-Math.PI,true);s.lineTo(13,-16.5);s.lineTo(-13,-16.5);s.lineTo(-13,-20.5);s.absarc(-16,-20.5,3,0,-Math.PI,true);s.lineTo(-19,-16.5);s.lineTo(-21,-16.5);s.lineTo(-21,-13.8);s.lineTo(-20,-12.8);s.lineTo(-20,-6.6);s.lineTo(-21,-5.6);s.closePath();return s;}
function board(host){const s=outline();s.holes.push(roundedRect(37,19,.04,{cx:0,cy:11.5,path:new THREE.Path()}));for(const[x,y]of spec.mountingHolesMm)hole(s,x,y,1.5);for(const[x,y]of spec.retainingHolesMm)hole(s,x,y,1.3);for(const x of[-15,15])for(const y of[-13.7,-11.7,-9.7,-7.7])hole(s,x,y,.32);
 const pcb=solid(host.body,s,1,[0,0,spec.pcbZ],materials.plastic(0x181f1a,{roughness:.86}),'Glass2 own-drawing black carrier PCB with true window,mount,retainer and8contact bores');pcb.userData={role:'physical-pcb',source:'Independent exact U158-B drawing reconstruction;no borrowed CAD'};const pads=[];for(const[x,y]of spec.mountingHolesMm)for(const z of[-3.182,-2.175])pads.push(ring(host.body,2.68,1.5,.007,[x,y,z],materials.metal(0x9c9e39,{roughness:.7}),'Glass2 actual annular exposed mounting-pad copper'));
 const parts=[],tin=materials.metal(0xb5bbb1,{roughness:.48}),black=materials.plastic(0x242a23,{roughness:.85});for(const[n,x,y,w,h,d]of[['U1 TPS61040DBVR',-5.5,-10.7,2.9,1.6,.9],['U2 ME6210A33M3G',5.2,-11.8,2.9,1.6,.9],['L1 10uH2520',-10,-12.5,2.5,2,1.2],['D1 1N4148WS',-8.9,-9.4,1.7,.9,.65]]){const o=mesh(host.body,new THREE.BoxGeometry(w,h,d),black,[x,y,-2.175+d/2],'Glass2 '+n+' physical package');o.userData={role:'concealed-package',placementInferred:true};parts.push(o);for(const sign of[-1,1])mesh(host.body,new THREE.BoxGeometry(.45,h*.7,.18),tin,[x+sign*(w/2+.12),y,-2.08],'Glass2 fixed package solder termination');}
 for(let i=0;i<18;i++){const x=-11.8+(i%6)*4.1,y=-14.8+Math.floor(i/6)*1.6;if(spec.retainingHolesMm.some(([a,b])=>Math.hypot(x-a,y-b)<3))continue;parts.push(mesh(host.body,new THREE.BoxGeometry(.95,.55,.45),i%3?materials.plastic(0xb9ac80,{roughness:.88}):black,[x,y,-1.95],'Glass2 concealed passive package'));}
 const jumper=[];for(const x of[6.5,7.2])jumper.push(mesh(host.body,new THREE.CylinderGeometry(.3,.3,.06,20).rotateX(Math.PI/2),tin,[x,-14.4,-2.135],'Glass2 actual unbridged SA0 address solder pad'));
 const connector=mesh(host.body,new THREE.BoxGeometry(13.2,2.2,1.55),materials.plastic(0xd1d1bd),[0,-9.7,-1.4],'Glass2 J3 actual24pin FPC connector insulator');const latch=mesh(host.body,new THREE.BoxGeometry(13.2,.65,.65),black,[0,-10.8,-.5],'Glass2 J3 fixed dark FPC locking bar');const contacts=[];for(let i=0;i<24;i++)contacts.push(mesh(host.body,new THREE.BoxGeometry(.2,2.4,.14),tin,[(i-11.5)*.5,-9.75,-.57],'Glass2 actual24pin FPC contact'));
 return{pcb,pads,parts,jumper,connector,latch,contacts};}
function panel(host){const p=spec.glass.position,glass=mesh(host.body,new THREE.BoxGeometry(...spec.glass.size),new THREE.MeshPhysicalMaterial({color:0xd8e5de,roughness:.08,metalness:0,transparent:true,opacity:.18,transmission:.72,thickness:1.25,ior:1.46,depthWrite:false,clearcoat:1}),p,'Glass2 real42.04×27.22×1.25 transparent glass volume');glass.userData={role:'physical-transparent-glass',scope:'Visual translucent material only;no calibrated optical throughput/refraction'};
 const edge=[];for(const[x,y,w,h]of[[-20.6,9.89,.42,27.22],[20.6,9.89,.42,27.22],[0,23.28,41.0,.4]])edge.push(mesh(host.body,new THREE.BoxGeometry(w,h,.35),materials.plastic(0x3e5148,{roughness:.6}),[x,y,-1.0],'Glass2 thin panel edge-seal border'));
 const driver=mesh(host.body,new THREE.BoxGeometry(39.6,2.8,.45),materials.plastic(0x1c2620,{roughness:.8}),[0,-2.0,-.9],'Glass2 actual opaque lower driver/COG strip outside active aperture');
 const flexShape=new THREE.Shape();flexShape.moveTo(-7.5,-3.35);flexShape.lineTo(7.5,-3.35);flexShape.lineTo(7.5,-5.5);flexShape.lineTo(5.95,-7.1);flexShape.lineTo(5.95,-11.0);flexShape.lineTo(-5.95,-11.0);flexShape.lineTo(-5.95,-7.1);flexShape.lineTo(-7.5,-5.5);flexShape.closePath();const flex=solid(host.body,flexShape,.12,[0,0,-.5],materials.plastic(0xbd7d20,{roughness:.72}),'Glass2 actual amber FPC tail with broad glass neck and24pin end');const fold=mesh(host.body,new THREE.BoxGeometry(15,.5,.55),materials.plastic(0xbd7d20,{roughness:.72}),[0,-3.5,-.65],'Glass2 physical FPC bend at glass contact edge');const tracks=[];for(let i=0;i<24;i++)tracks.push(mesh(host.body,new THREE.BoxGeometry(.12,6.6,.015),materials.metal(0x8d5915,{roughness:.75}),[(i-11.5)*.5,-7.35,-.371],'Glass2 actual FPC fine contact strip'));
 const tailFront=mesh(host.body,new THREE.BoxGeometry(12,5.7,.12),materials.plastic(0xbd7d20,{roughness:.72}),[0,-13.85,-.5],'Glass2 actual visible amber FPC tail below cover');
 const tailReturn=mesh(host.body,new THREE.BoxGeometry(12,6.2,.12),materials.plastic(0xbd7d20,{roughness:.72}),[0,-13.6,-2],'Glass2 actual FPC retained return to24pin connector');
 const foldSection=new THREE.Shape();foldSection.moveTo(0,.81);foldSection.absarc(0,0,.81,Math.PI/2,Math.PI*1.5,false);foldSection.lineTo(0,-.69);foldSection.absarc(0,0,.69,Math.PI*1.5,Math.PI/2,true);foldSection.closePath();const bendGeometry=new THREE.ExtrudeGeometry(foldSection,{depth:12,bevelEnabled:false,curveSegments:48}).applyMatrix4(new THREE.Matrix4().makeBasis(new THREE.Vector3(0,1,0),new THREE.Vector3(0,0,1),new THREE.Vector3(1,0,0)));const returnFold=mesh(host.body,bendGeometry,materials.plastic(0xbb7b20,{roughness:.72}),[-6,-16.7,-1.25],'Glass2 real closed half-annular FPC return fold below PCB cover');
 for(let i=0;i<24;i++)tracks.push(mesh(host.body,new THREE.BoxGeometry(.12,5.7,.015),materials.metal(0x8d5915,{roughness:.75}),[(i-11.5)*.5,-13.85,-.432],'Glass2 visible folded FPC fine track'));
 const screen=host.add(new TransparentOled());return{glass,edge,driver,flex,fold,tracks,tailFront,tailReturn,returnFold,screen};}
function socket(host,right=false){const specPort=right?spec.groveRight:spec.grove,id=right?'grove-right':'grove',g=new THREE.Group();g.name='Glass2 '+(right?'right':'left')+' white open HY2.0-4P socket';g.position.fromArray(specPort.position);g.quaternion.copy(FACE[specPort.face]);host.body.add(g);const plastic=materials.plastic(specPort.color,{roughness:.73}),metal=materials.metal(0xbeb7a4,{roughness:.5}),box=(s,p,n,m=plastic)=>mesh(g,new THREE.BoxGeometry(...s),m,p,'Glass2 '+id+' '+n),d=6.6;
 for(const sign of[-1,1]){box([.65,5.2,d],[sign*4.675,0,-d/2],'side wall');box([.7,.6,3.2],[sign*3.85,2.3,-4.9],'guide rail');box([.6,.45,1.2],[sign*3.65,2.375,-1.8],'latch shoulder');}box([8.7,.65,d],[0,-2.275,-d/2],'floor');box([8.7,4.55,.65],[0,.325,-d+.325],'deep rear wall');box([4.8,.45,2.3],[0,2.375,-4.6],'locking bridge');const contacts=[],tails=[];for(let i=0;i<4;i++){contacts.push(box([.42,.42,4.7],[(i-1.5)*2,.2,-3.7],'actual metal contact '+(i+1),metal));tails.push(box([.42,1,.42],[(i-1.5)*2,-3.1,-6],'actual through-board tail '+(i+1),metal));}
 const port=host.add(new Port({id,label:(right?'Right':'Left')+' PORT.A · parallel I2C physical socket',connector:'grove',position:specPort.position,quaternion:portQuaternion(specPort.face),hitSize:[10,1,5.2],pins:[{n:1,name:'GND',color:'black'},{n:2,name:'5V',color:'red'},{n:3,name:'SDA',color:'yellow'},{n:4,name:'SCL',color:'white'}],meta:{role:'visual-connector',face:specPort.face,documentedTopology:'Both J1/J2 share I2C and supply;either physical socket usable',scope:'Independent physical attachment and cable pose only;no I2C transactions,pass-through signal simulation,supply,SA0 address or electrical behavior.'}}));return{group:g,contacts,tails,port};}
function cover(host){const black=materials.plastic(0x151c16,{roughness:.83}),metal=materials.metal(0xaab3aa,{roughness:.48}),s=roundedRect(42,14,.16);for(const[x]of spec.retainingHolesMm)hole(s,x,2,2.0);const plate=solid(host.body,s,.55,spec.cover.position,black,'Glass2 actual fixed black service cover with real2screw bores');
 const filmShape=roundedRect(42,14,.16);for(const[x]of spec.retainingHolesMm)hole(filmShape,x,2,2.0);const film=solid(host.body,filmShape,.05,[0,-9,3.125],materials.plastic(0x101610,{roughness:.86}),'Glass2 physical front label film seated on service cover');const columns=[],screws=[];
 for(const[x,y]of spec.retainingHolesMm){const column=ring(host.body,1.95,.9,4.75,[x,y,-2.175],materials.metal(0x303c32,{roughness:.64}),'Glass2 actual metal hollow threaded cover standoff');columns.push(column);const screw=new THREE.Group();screw.name='Glass2 real fixed hex socket cover screw';screw.position.set(x,y,3.125);host.body.add(screw);const head=new THREE.Shape();head.absarc(0,0,1.94,0,tau,false);const hex=new THREE.Path();for(let i=0;i<6;i++){const a=i*tau/6,u=Math.cos(a)*.85,v=Math.sin(a)*.85;i?hex.lineTo(u,v):hex.moveTo(u,v);}hex.closePath();head.holes.push(hex);const ringHead=solid(screw,head,.55,[0,0,-.55],metal,'Glass2 real annular screw head with hex socket');const floor=mesh(screw,new THREE.CylinderGeometry(.86,.86,.08,6).rotateX(Math.PI/2),materials.metal(0x59665b),[0,0,-.51],'Glass2 screw deep blind hex floor');const shank=mesh(screw,new THREE.CylinderGeometry(.74,.74,5.7,32).rotateX(Math.PI/2),metal,[0,0,-3.1],'Glass2 fixed screw full internal shank');screws.push({group:screw,head:ringHead,floor,shank});}
 return{plate,film,columns,screws};}
export function buildGlass2(host){const pcb=board(host),oled=panel(host),left=socket(host),right=socket(host,true),cap=cover(host);host.glass2Assembly={board:pcb,panel:oled,left,right,cover:cap};host.unitStickers=addStickers(host);}
